questions.solution:
function parseQuantity(text) {
  const n = Number(text.trim());
  if (text.trim() === "" || !Number.isInteger(n) || n < 1 || n > 99) return null;
  return n;
}

console.log(parseQuantity("3"), parseQuantity(""), parseQuantity("abc"), parseQuantity("2.5"), parseQuantity("150"));

